def bigThan(a, b):
    if a == 1 and b == 1:
        return False
    elif a == 1 and b != 1:
        return True
    elif a != 1 and b == 1:
        return False
    else:
        return a > b


def judge(a, b):

    if a == b:
        return "Draw"
    elif bigThan(a, b):
        return "Alice"
    else:
        return "Bob"

