import sys

def solve(w, a, b):
    ans = 0

    if w + b < a:
        ans = a - (b + w)
    elif (a <= b + w) and (b <= a + w):
        ans = 0
    else:
        return b - (a + w)
    return ans

def main():
    line = sys.stdin.readline()
    w, a, b = [ int(s) for s in line.split()]

    ans = solve(w, a, b)
    print(ans)
    return 0

