def is_visited(v: int, path: int):
    return path & (1 << v)


def visit(v: int, path: int):
    return path ^ (1 << v)


def count(u: int, path: int):
    if path == G:
        return 1

    k = (u, path)
    if k in dp:
        return dp[k]

    s = sum(
        count(v, visit(v, path))
        for v in E[u]
        if not is_visited(v, path)
    )
    dp[k] = s
    return s


