        if candies[i-1] > x:
            base += candies[i-1] - x
            candies[i-1] -= candies[i-1] - x
            base += candies[i] + candies[i-1] - x
            candies[i] -= candies[i] + candies[i-1] - x
        elif candies[i-1] <= x:
            base += candies[i] + candies[i-1] - x
            candies[i] -= candies[i] + candies[i-1] - x
    return base


