def c_Boxes_and_Candies(N, X, A):
    a = [x for x in A]
    if a[0] > X:
        # 最初からXを超えていた場合、減らさなければ条件を満たせない
        a[0] = X
    for i in range(0, N - 1):
        if a[i] + a[i + 1] > X:
            # a[i]+a[i+1]==Xになるまで減らす。a[i+1]だけ減らしたほうが得する
            a[i + 1] = X - a[i]
    ans = 0
    for i in range(N):
        ans += A[i] - a[i]
    return ans

