import sys
from collections import defaultdict

def main():
    n = int(sys.stdin.readline())

    line = sys.stdin.readline()
    lst = line.split()

    cnt_dic = defaultdict(int)

    #400で割ったときの商が0,1,2,3,4,5,6,7
    #8以上は、自由に色を決められる

    for ch in lst:
        rating = int(ch)
        n = rating // 400
        if n <= 7:
            cnt_dic[n] += 1
        else:
            cnt_dic[8] += 1

    ans_max = 0
    ans_min = 0
    for i in range(0,8):
        if cnt_dic[i] > 0:
            ans_max += 1
            ans_min += 1

    if cnt_dic[8] > 0:
        ans_max += cnt_dic[8]
        if ans_min == 0:
            ans_min += 1

    print("%d %d" % (ans_min, ans_max))
    return 0

if __name__ == '__main__':
    sys.exit(main())

