sys.setrecursionlimit(300000)

YES = "Yes"  # type: str
NO = "No"  # type: str

def solve(w: str):
    count = [0] * 26
    for c in w:
        count[ord(c) - ord('a')] += 1
    for cnt in count:
        if cnt % 2:
            print(NO)
            return
    print(YES)
    return


