def indexIsValid(S, ni):
    for i in range(len(S)):
        if ni[i] >= len(S[i]):
            return False

    return True

def goToNextCharacterIndex(S, ni, current_c):
    for i in range(len(S)):
        while S[i][ni[i]] == current_c:
            ni[i] += 1

            # end of search
            if ni[i] >= len(S[i]):
                return False

    return True

def allSameCharacter(S, ni):
    result = True
    for i in range(len(S) - 1):
        result = result and (S[i][ni[i]] == S[i+1][ni[i+1]])

    return result


