class BellmanFord:
    INF = int(1e18)
    N = -1
    edge = []

    def __init__(self, N):
        self.N = N

    def add_edge(self, frm, to, cost):
        self.edge.append((frm, to, cost));

    def add_bi_edge(self, a, b, cost):
        self.add_edge(a, b, cost)
        self.add_edge(b, a, cost)

    def calcD(self, start):
        D = [self.INF] * self.N
        D[start] = 0
        update, cnt = True, 0
        flag = False
        while update:
            cnt = cnt + 1
            if cnt > self.N:
                return D if flag == False else 'NegativeCycle'
            update = False
            flag = False

            for frm, to, cost in self.edge:
                ncost = D[frm] + cost
                if D[frm] == self.INF or ncost >= D[to]:
                    continue
                D[to] = ncost
                update = True
                flag = flag | (to == self.N-1)

        return D


