def dfs(N, Adj, visited, u):
    for v in Adj[u]:
        if not visited[v]:
            visited[v] = True
            dfs(N, Adj, visited, v)

def BellmanFord(N, M, edges):
    d = [inf] * N
    d[0] = 0

    for i in range(N - 1):
        for (ai, bi, ci) in edges:
            if d[ai] != inf and d[ai] + ci < d[bi]:
                d[bi] = d[ai] + ci

    for (ai, bi, ci) in edges:
        if d[ai] != inf and d[ai] + ci < d[bi]:
            return None

    return d[N - 1]

