    X,Y,N = map(int,input().split())
    mapx=makemap(X,Y)
    count = 0
    for k in range(0,N):
        x,y,a = map(int,input().split())
        mapx = drow(X,Y,x,y,a,mapx)
    for i in range(0,X):
        for j in range(0,Y):
            if mapx[i][j]==0:
                count+=1
    print(count)

