    for i in range(len(bi)):
        v = 0
        for j in range(len(bi[i])):
            if bi[i][j] == "1":
                lis[i].append(int(s[v:j+1]))
                v = j+1
            if j == len(bi[i])-1:
                lis[i].append(int(s[v:]))
    return lis

