def sum_of_digit(d, l, s): #d: その位の数が何か l: 桁の数 s:下から何桁目か 下に置ける+は2^(s-1)通り 上に置ける+は2^(l-s)通り
    # 2^(s-2) * 10^0 | 2^(s-3) * 10^1 | ... | 2^0 * 10^(s-2) | 1 * 10^(s-1)
    if s == 0:
        return d * (2 ** (l - s))
    else:
        digits = [(2 ** (s - 2 - i)) * (10 ** i) for i in range(s - 1)] + [10 ** (s - 1)]
        return d * (2 ** (l - s)) * sum(digits)

