def formulas(s):
    formula_list = []
    def aux(current, i):
        if i < len(s):
            aux(current + [s[i]], i + 1)
            aux(current + ['+', s[i]], i + 1)
        else:
            formula_list.append(''.join(current))                

    aux([s[0]], 1)
    return formula_list


